"""
Hilfsfunktionen fuer HTTP-Anfragen mit Wiederholungsmechanismus.

Verwendung:
    from core_services.utils import retry_request
"""

import logging
import time
from collections.abc import Callable
from typing import Any

import requests

logger = logging.getLogger(__name__)

# Erwartete Erfolgs-Statuscodes pro HTTP-Methode.
SUCCESS_CODES: dict[str, list[int]] = {
    "GET": [200, 204],
    "POST": [200, 201, 204],
    "PATCH": [200, 204],
    "PUT": [200, 204],
    "DELETE": [200, 204],
}

# Mapping von Methoden-Namen auf requests-Funktionen.
_METHOD_MAP: dict[str, Callable[..., requests.Response]] = {
    "GET": requests.get,
    "POST": requests.post,
    "PATCH": requests.patch,
    "PUT": requests.put,
    "DELETE": requests.delete,
}


def retry_request(
    method: str,
    url: str,
    *,
    max_attempts: int = 10,
    retry_delay: float | None = None,
    **kwargs: Any,
) -> requests.Response | None:
    """Fuehrt eine HTTP-Anfrage mit Wiederholungsmechanismus durch.

    Prueft automatisch anhand der HTTP-Methode (GET, POST, PATCH, PUT, DELETE),
    welche status-Codes als Erfolg gewertet werden. Die Zuordnung erfolgt ueber
    das Modul-Dictionary SUCCESS_CODES.

    Args:
        method: Die HTTP-Methode als String, z. B. "GET", "POST", "PATCH", "PUT", "DELETE".
        url: Die Ziel-URL fuer die Anfrage.
        max_attempts: Maximale Anzahl der HTTP-Anfragen.
        retry_delay: Feste Wartezeit zwischen Versuchen in Sekunden. Bei None
            wird exponentieller Backoff mit maximal zehn Sekunden verwendet.
        **kwargs: Zusaetzliche Argumente fuer requests, z. B. headers, json oder verify.

    Returns:
        Die Response des Servers bei Erfolg oder None, wenn alle Versuche fehlschlagen.

    Raises:
        ValueError: Wenn die Retry-Konfiguration ungueltig oder die HTTP-Methode
            nicht unterstuetzt ist.
    """
    if max_attempts < 1:
        raise ValueError("max_attempts muss mindestens 1 sein")
    if retry_delay is not None and retry_delay < 0:
        raise ValueError("retry_delay darf nicht negativ sein")

    method_name = method.upper()
    request_func = _METHOD_MAP.get(method_name)
    if request_func is None:
        raise ValueError(f"Unbekannte HTTP-Methode: {method}")

    expected_codes = SUCCESS_CODES.get(method_name, [200])
    response: requests.Response | None = None

    for attempt in range(max_attempts):
        try:
            response = request_func(url, **kwargs)
            if response.status_code in expected_codes:
                return response

            logger.warning(
                "Attempt %s: %s %s returned %s (expected: %s)",
                attempt + 1,
                method_name,
                url,
                response.status_code,
                expected_codes,
            )
        except requests.RequestException as exc:
            logger.error("Attempt %s: Exception %s for %s %s", attempt + 1, exc, method_name, url)

        if attempt < max_attempts - 1:
            delay = retry_delay if retry_delay is not None else min(2**attempt, 10)
            time.sleep(delay)

    logger.error(
        "%s %s nach %s Versuchen fehlgeschlagen. Letzter bekannter status: %s",
        method_name,
        url,
        max_attempts,
        response.status_code if response is not None else "Keine Antwort",
    )
    return None
